const HULL_SPLIT = 4272;   // triangles before this index are the shell, after it the socket recesses
let hullGeo = null;
function getHullGeo() {
  if (hullGeo) return hullGeo;
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(HULL_V, 3));
  g.setIndex(HULL_I);
  // two material groups: 0 = the shell (primary colour), 1 = the round socket recesses (secondary colour)
  g.addGroup(0, HULL_SPLIT, 0); g.addGroup(HULL_SPLIT, HULL_I.length - HULL_SPLIT, 1);
  hullGeo = g.toNonIndexed();          // flat shading: every facet keeps its own crisp normal
  hullGeo.computeVertexNormals();
  return hullGeo;
}
